def _probabilities(
    values: Sequence[float],
    bandwidth_c: float = KERNEL_BANDWIDTH_C,
) -> dict[str, float]:
    """Bucket probabilities from a kernel-dressed sample, not a histogram.

    A histogram of a few dozen discrete values serves zeros even beside its
    own mean -- settled truth landed at a calibrated center of 30.0C while
    the 30C bucket held no member and was served as impossible.  Each value
    is dressed with a normal kernel instead, so mass decays with distance
    the way the sample's own shape says it should; a bucket far from every
    member is small because the model puts little there, not zero because
    the sample is finite.
    """

    if not values:
        raise ContractError("native_ensemble_oos_values_missing")
    current = []
    for value in values:
        if not math.isfinite(float(value)):
            raise ContractError("native_ensemble_oos_value_invalid")
        current.append(float(value))
    bandwidth = float(bandwidth_c)
    # Variance-preserving: shrink deviations so sample variance plus kernel
    # variance reproduces the original.  The calibration already chose the
    # distribution's width; dressing may not change it, only make it smooth.
    mean = sum(current) / len(current)
    std = math.sqrt(
        sum((v - mean) ** 2 for v in current) / len(current)
    )
    if std > bandwidth:
        shrink = math.sqrt(1.0 - (bandwidth / std) ** 2)
        current = [mean + shrink * (v - mean) for v in current]
    lo = math.floor(min(current) - 4.0 * bandwidth)
    hi = math.ceil(max(current) + 4.0 * bandwidth)
    def _cdf(x: float, mu: float) -> float:
        return 0.5 * (1.0 + math.erf((x - mu) / (bandwidth * math.sqrt(2.0))))
    result: dict[str, float] = {}
    for bucket in range(int(lo), int(hi) + 1):
        mass = sum(
            _cdf(bucket + 0.5, mu) - _cdf(bucket - 0.5, mu)
            for mu in current
        ) / len(current)
        if mass > 0.0:
            result[str(bucket)] = mass
    total = sum(result.values())
    return {
        bucket: value / total
        for bucket, value in sorted(
            result.items(), key=lambda item: int(item[0])
        )
    }

def _resolved_bias_c(
    mean: float,
    parameters: Mapping[str, Any],
) -> float:
    """The shift this centre actually earns, whatever form fitted it.

    One resolver for the evaluator and the server -- the affine incident was
    exactly these two disagreeing -- so the form gate lives here: a
    parameters payload naming a form this build cannot run is refused, never
    silently served as the constant.
    """

    form = str(parameters.get("correction_form") or "constant")
    if form == "constant":
        return float(parameters["bias_c"])
    if form == BIAS_CORRECTION_FORM:
        cuts = [float(cut) for cut in parameters["bias_bin_cuts_c"]]
        shifts = [
            float(shift) for shift in parameters["bias_bin_shifts_c"]
        ]
        if not shifts or len(shifts) != len(cuts) + 1:
            raise ContractError(
                "native_ensemble_oos_binned_bias_malformed"
            )
        return shifts[_level_bin(float(mean), cuts)]
    raise ContractError(
        "native_ensemble_oos_correction_form_unsupported"
    )

def _interval_probability(
    values: Sequence[float],
    intervals: Mapping[str, Sequence[float | None]],
    bandwidth_c: float | None = None,
) -> dict[str, float]:
    """Integrate a kernel-dressed sample over the bucket contract.

    A histogram of a few dozen discrete values serves zeros even beside its
    own mean: truth once settled at a calibrated center of 30.0C while the
    30C bucket held no member and was served as impossible.  Dressing each
    value with a normal kernel makes mass decay with distance the way the
    sample's own shape says it should -- a far bucket is small because the
    model puts little there, never zero because the sample is finite.  The
    open edge buckets integrate their whole tails, so the contract still
    receives exactly the full unit of mass.
    """

    if not values:
        raise ContractError("native_ensemble_p0_values_missing")
    current: list[float] = []
    for raw_value in values:
        value = float(raw_value)
        if not math.isfinite(value):
            raise ContractError("native_ensemble_p0_value_invalid")
        current.append(value)
    count = len(current)
    mean = sum(current) / count
    if count > 1:
        std = math.sqrt(
            sum((v - mean) ** 2 for v in current) / count
        )
    else:
        std = 0.0
    # Half a degree: the discreteness scale, not a smoothing choice --
    # Silverman-sized bandwidths were rejected by the holdout for widening
    # what the calibration had already sized.  Deviations shrink so sample
    # variance plus kernel variance reproduces the original: dressing may
    # not change the width the calibration chose, only make it smooth.
    # A caller may widen it explicitly -- a lone point member has no sample
    # variance, so its calibrated width must arrive through the kernel.
    bandwidth = 0.5 if bandwidth_c is None else float(bandwidth_c)
    if std > bandwidth:
        shrink = math.sqrt(1.0 - (bandwidth / std) ** 2)
        current = [mean + shrink * (v - mean) for v in current]
    sqrt2 = math.sqrt(2.0)

    def _cdf(x: float) -> float:
        return sum(
            0.5 * (1.0 + math.erf((x - mu) / (bandwidth * sqrt2)))
            for mu in current
        ) / count

    probability: dict[str, float] = {}
    for bucket, bounds in intervals.items():
        if (
            not isinstance(bounds, Sequence)
            or isinstance(bounds, (str, bytes, bytearray))
            or len(bounds) != 2
        ):
            raise ContractError(
                "native_ensemble_p0_bucket_interval_invalid"
            )
        lower, upper = bounds
        upper_mass = 1.0 if upper is None else _cdf(float(upper))
        lower_mass = 0.0 if lower is None else _cdf(float(lower))
        probability[str(bucket)] = max(0.0, upper_mass - lower_mass)
    total = sum(probability.values())
    if not 0.999 <= total <= 1.001:
        # The intervals no longer partition the line; a histogram would have
        # caught this per value, the integral catches it in aggregate.
        raise ContractError(
            "native_ensemble_p0_bucket_contract_not_exhaustive"
        )
    return {
        bucket: value / total
        for bucket, value in probability.items()
    }

def _centre_distances(
    probability: "Mapping[str, float]",
    ordinals: "Mapping[str, int]",
) -> dict[str, float]:
    """How many buckets each key sits from the distribution's own peak.

    The peak, not the mean: the mean moves under the map and the argmax
    does not, which is the whole reason this axis is stable.  Ties break on
    the ordinal so two runs of the same vector agree.
    """

    ranked = [
        (float(value), -int(ordinals[key]), str(key))
        for key, value in probability.items()
        if key in ordinals
    ]
    if not ranked:
        raise ValueError("band_reliability_ordinals_missing")
    centre = max(ranked)[2]
    centre_ordinal = int(ordinals[centre])
    return {
        str(key): float(abs(int(ordinals[key]) - centre_ordinal))
        for key in probability
        if key in ordinals
    }
